-- ============================================================================
-- Capital Edge Stellar - multiple organizations per login
--
-- Run this AFTER schema.sql. Lets one person (one email, one login) create
-- and belong to more than one organization - matching how Zoho and most
-- real multi-tenant accounting tools work: one account, several separate
-- companies, each with its own completely separate books and its own
-- separate subscription.
--
-- This needed almost no new database structure. company_members already
-- links a user_id to a company_id with a role - nothing about that table
-- stopped one user_id from having a row in several different companies.
-- The actual gap was entirely in the application: AuthGate only ever
-- fetched the first membership it found and stopped there. This function
-- is the one genuinely new piece: a safe, atomic way for an already
-- logged-in user to spin up an additional organization on demand, which
-- didn't exist before (the only thing that created a company before now
-- was the signup trigger, and that only ever fires once, at signup).
-- ============================================================================

-- Creates a new, empty organization and makes the calling user its Admin,
-- as a single atomic action - there's no risk of ending up with a company
-- that has no members (which would be permanently inaccessible), because
-- both inserts either succeed together or neither happens at all.
--
-- IMPORTANT: the placeholder JSONB below must be kept in sync with
-- emptyCompanyData.js the same way schema.sql's is - see
-- DEPLOYMENT-GUIDE.md. It's duplicated here (rather than referencing
-- schema.sql's copy) because SQL has no clean way to share a literal
-- between two independent statements - both copies get regenerated
-- together whenever the chart of accounts changes.
create or replace function create_organization(org_name text)
returns uuid
language plpgsql
security definer set search_path = public
as $$
declare
  new_company_id uuid;
  caller uuid := auth.uid();
begin
  if caller is null then
    raise exception 'Not authenticated';
  end if;

  insert into companies (owner_id, name, data)
