"description":"","taxAccountId":"","currency":"","id":"4200","code":"4200","name":"Sales Returns & Allowances","type":"revenue","contra":true,"normal":"debit","category":"Operating Income","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5000","code":"5000","name":"Cost of Goods Sold","type":"expense","subtype":"cogs","category":"Cost of Goods Sold (COGS)","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5010","code":"5010","name":"Direct Materials","type":"expense","subtype":"cogs","category":"Cost of Goods Sold (COGS)","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5020","code":"5020","name":"Direct Labour","type":"expense","subtype":"cogs","category":"Cost of Goods Sold (COGS)","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5030","code":"5030","name":"Carriage / Freight Inwards","type":"expense","subtype":"cogs","category":"Cost of Goods Sold (COGS)","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5040","code":"5040","name":"Production Overheads","type":"expense","subtype":"cogs","category":"Cost of Goods Sold (COGS)","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5100","code":"5100","name":"Rent Expense","type":"expense","category":"Operating Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5200","code":"5200","name":"Utilities Expense","type":"expense","category":"Operating Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5300","code":"5300","name":"Payroll Expense","type":"expense","category":"Operating Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5400","code":"5400","name":"Office Supplies","type":"expense","category":"Operating Expenses","status":