urrent Liabilities","subtype":"current","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"2296","code":"2296","name":"Goods Received Not Invoiced","type":"liability","category":"Current Liabilities","subtype":"current","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"3900","code":"3900","name":"Opening Balance Equity","type":"equity","category":"Opening Balance Equity","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"6010","code":"6010","name":"Foreign Exchange Gain / (Loss)","type":"revenue","subtype":"other","category":"Other Income","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5760","code":"5760","name":"Impairment Loss","type":"expense","category":"Other Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5770","code":"5770","name":"Provision Expense","type":"expense","category":"Other Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"5780","code":"5780","name":"Revaluation Loss","type":"expense","category":"Other Expenses","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"2295","code":"2295","name":"Provisions","type":"liability","category":"Non-Current Liabilities","subtype":"noncurrent","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"3200","code":"3200","name":"Revaluation Surplus","type":"equity","category":"Reserves","status":"active"},{"parentId":null,"description":"","taxAccountId":"","currency":"","id":"6000","code":"6000","name":"Realized Gains & Losses","type":"revenue","subtype":"other","category":"Other Income","status":"active"}],"banks":[],"transactions":[],"invoices":[],"bills":[],"expenses":[],"inventory":[],"inventoryLots":[],"fixedAssets":[],"payments":[],"taxGroups":[],"projects":[],"locations":[],"departments":[],"users":[],"messages":[],"budgets":{},"budgetAccounts":[],"favoriteReports":["pl","ar-aging","inventory-summary"],"bankFeed":[],"categoryRules":[],"bin":[],"employees":[],"payrollRuns":[],"recurringJournals":[],"reconciliations":[],"auditLog":[],"taxProvisions":[],"leases":[],"deferredRevenueSchedules":[],"provisions":[],"salesOrders":[],"salesReceipts":[],"creditNotes":[],"salesReturns":[],"purchaseOrders":[],"purchaseReceipts":[],"vendorCredits":[],"timesheets":[],"productionRecords":[],"nextProductionNum":1,"openingBalances":{"asOfDate":"2026-07-30","accountAmounts":{},"customerBalances":[],"vendorBalances":[],"posted":false,"postedDate":null},"nextInvoiceNum":1001,"nextBillNum":2001,"nextSalesOrderNum":1,"nextSalesReceiptNum":1,"nextCreditNoteNum":1,"nextSalesReturnNum":1,"nextPurchaseOrderNum":1,"nextPurchaseReceiptNum":1,"nextVendorCreditNum":1}
'::jsonb)
  returning id into new_company_id;

  insert into company_members (company_id, user_id, email, name, role)
  select new_company_id, caller, u.email, coalesce(u.raw_user_meta_data->>'name', ''), 'admin'
  from auth.users u where u.id = caller;

  return new_company_id;
end;
$$;

-- Lets any authenticated user call the function above. The function
-- itself is what actually restricts what happens (always creates the
-- company under the caller's own auth.uid(), never anyone else's) - this
-- grant just permits calling it at all.
grant execute on function create_organization(text) to authenticated;
